<script setup lang="ts">import{computed}from'vue';import MathFormula from'../../../components/MathFormula.vue';import type{CircularPlateResult}from'../../../core/plate-shell';import{formatEngineeringValue}from'../../../core/numeric';import{convertFromSI,getPresetUnit,getUnitDefinition,type UnitPresetId}from'../../../core/units';const p=defineProps<{result:CircularPlateResult;unitPreset:UnitPresetId}>();const u=computed(()=>({l:getPresetUnit('length',p.unitPreset),s:getPresetUnit('stress',p.unitPreset),m:getPresetUnit('momentPerLength',p.unitPreset),f:getPresetUnit('force',p.unitPreset),q:getPresetUnit('lineLoad',p.unitPreset)}));const cv=(v:number,q:'length'|'stress'|'momentPerLength'|'force'|'lineLoad',id:keyof typeof u.value)=>formatEngineeringValue(convertFromSI(v,q,u.value[id]));const sy=(q:'length'|'stress'|'momentPerLength'|'force'|'lineLoad',id:keyof typeof u.value)=>getUnitDefinition(q,u.value[id]).symbol</script>
<template><section class="results" data-testid="circular-plate-results"><header><h3>圆板挠度、弯矩与表面应力</h3><span>精确闭式解</span></header><div v-for="w in result.warnings" :key="w" class="warning">{{w}}</div><div class="summary"><article><small>弯曲刚度 D</small><strong>{{formatEngineeringValue(result.rigidityNm)}} N·m</strong></article><article><small>中心/最大挠度</small><strong>{{cv(result.maximumDeflectionM,'length','l')}} {{sy('length','l')}}</strong></article><article><small>边缘线反力 Qr</small><strong>{{cv(result.edgeLineReactionNPerM,'lineLoad','q')}} {{sy('lineLoad','q')}}</strong></article><article><small>总反力</small><strong>{{cv(result.totalReactionN,'force','f')}} {{sy('force','f')}}</strong></article></div><div class="points"><article v-for="pt in result.points" :key="pt.label" :data-testid="`circular-point-${pt.label}`"><h4>{{pt.label}} · r={{cv(pt.radiusM,'length','l')}} {{sy('length','l')}}</h4><p>挠度 w：<b>{{cv(pt.deflectionM,'length','l')}} {{sy('length','l')}}</b></p><p>Mr / Mθ：<b>{{cv(pt.radialMomentN,'momentPerLength','m')}} / {{cv(pt.hoopMomentN,'momentPerLength','m')}} {{sy('momentPerLength','m')}}</b></p><p>正面 σr / σθ：<b>{{cv(pt.positiveRadialStressPa,'stress','s')}} / {{cv(pt.positiveHoopStressPa,'stress','s')}} {{sy('stress','s')}}</b></p><p>反面 σr / σθ：<b>{{cv(pt.negativeRadialStressPa,'stress','s')}} / {{cv(pt.negativeHoopStressPa,'stress','s')}} {{sy('stress','s')}}</b></p></article></div><details open><summary>公式与适用范围</summary><MathFormula :formula="result.boundary==='clamped'?'w=q(a^2-r^2)^2/(64D)':'w=q(a^2-r^2)\{[(5+\nu)/(1+\nu)]a^2-r^2\}/(64D)'"/><p>公式 ID：{{result.formulaId}}；仅等厚实心圆板、小挠度轴对称均布载荷。</p></details></section></template>
<style scoped>.results{padding:22px;border:1px solid var(--color-line);border-radius:var(--radius-large);background:#fff;box-shadow:var(--shadow-panel)}header{display:flex;justify-content:space-between;gap:12px}h3,h4{margin:0}header span{padding:6px 9px;border-radius:99px;color:#25613d;background:#e7f5ec;font-size:11px}.warning{margin-top:12px;padding:11px;border-left:4px solid #c37a20;background:#fff8e9}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-top:15px;background:var(--color-line)}.summary article,.points article{padding:13px;background:#fff}.summary small{display:block;color:var(--color-muted)}.points{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px}.points article{border:1px solid var(--color-line);border-radius:9px}.points p{font-size:11px}details{margin-top:15px;font-size:11px}@media(max-width:850px){.summary{grid-template-columns:repeat(2,1fr)}.points{grid-template-columns:1fr}}@media(max-width:520px){.summary{grid-template-columns:1fr}}</style>
